type StoredTool =
  | {definitionSource: ToolDefinition; execute: ToolExecutor; validateInput: ValidateFunction}
  | {
      definitionSource: () => ToolDefinition;
      execute: ToolExecutor;
      schemaCache: WeakMap<Record<string, unknown>, ValidateFunction>;
    };

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private resolveValidator(tool: StoredTool): ValidateFunction {
    if ('validateInput' in tool) return tool.validateInput;
    const resolved = tool.definitionSource();
    const {schemaCache} = tool;
    const cached = schemaCache.get(resolved.inputSchema);
    if (cached) return cached;
    const compiled = compileSchema(resolved.name, resolved.inputSchema);
    schemaCache.set(resolved.inputSchema, compiled);
    return compiled;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const compiled = compileSchema(resolved.name, resolved.inputSchema);
    if (typeof definition === 'function') {
      const schemaCache = new WeakMap<Record<string, unknown>, ValidateFunction>();
      schemaCache.set(resolved.inputSchema, compiled);
      this.tools.set(resolved.name, {definitionSource: definition, execute, schemaCache});
      return;
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validateInput: compiled});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against inputSchema; throws only if unknown (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = this.resolveValidator(tool);
    if (!validate(input)) {
      const reason = formatValidationErrors(validate.errors ?? []);
      log.warn('tool', 'rejected input', {name, reason});
      return {result: `Invalid input for tool "${name}": ${reason}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});

function compileSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${reason}`, {cause: error});
  }
}

function formatValidationErrors(errors: ErrorObject[]): string {
  return errors.map(formatValidationError).join('; ');
}

type KeywordFormatter = (path: string, params: Record<string, unknown>) => string | undefined;

const keywordFormatters: Record<string, KeywordFormatter> = {
  required: (path, params) => {
    const missing = params.missingProperty;
    if (typeof missing !== 'string') return undefined;
    const fullPath = path ? `${path}.${missing}` : missing;
    return `${fullPath} is required`;
  },
  type: (path, params) => {
    const expected = params.type;
    if (typeof expected !== 'string') return undefined;
    const field = path || 'input';
    return `${field} must be ${expected}`;
  },
  enum: (path, params) => {
    const allowed = params.allowedValues;
    if (!Array.isArray(allowed)) return undefined;
    const field = path || 'input';
    const labels = allowed.map(entry => JSON.stringify(entry));
    return `${field} must be one of: ${labels.join(', ')}`;
  },
};

function formatValidationError(error: ErrorObject): string {
  const path = extractErrorPath(error);
  const formatter = Object.hasOwn(keywordFormatters, error.keyword) ? keywordFormatters[error.keyword] : undefined;
  const formatted = formatter ? formatter(path, error.params) : undefined;
  if (formatted) return formatted;
  const field = path || 'input';
  return `${field}: ${error.message ?? error.keyword}`;
}

function extractErrorPath(error: ErrorObject): string {
  const pointer = error.instancePath;
  if (typeof pointer === 'string') {
    return pointer.replace(/^\//, '').replaceAll('/', '.');
  }
  if ('dataPath' in error && typeof error.dataPath === 'string') {
    const legacyPath = error.dataPath;
    return legacyPath.replace(/^\./, '');
  }
  return '';
}

