import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry', () => {
  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('passes valid input with undeclared extra properties through to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(weatherDefinition(), async input => {
      receivedInputs.push(input);
      return String(input.location);
    });

    const response = await registry.execute('get_weather', {location: 'Berlin', extra: 42});

    expect({response, receivedInputs}).toEqual({
      response: {result: 'Berlin'},
      receivedInputs: [{location: 'Berlin', extra: 42}],
    });
  });

  it('rejects a disallowed enum value without echoing the offending value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(weatherDefinition(), async () => {
      executorCalls += 1;
      return 'unreachable';
    });

    const response = await registry.execute('get_weather', {location: 'Berlin', units: 'kelvin'});

    expect({
      executorCalls,
      mentionsField: response.result.includes('units'),
      mentionsAllowedValue: response.result.includes('celsius'),
      echoesOffendingValue: response.result.includes('kelvin'),
    }).toEqual({
      executorCalls: 0,
      mentionsField: true,
      mentionsAllowedValue: true,
      echoesOffendingValue: false,
    });
  });

  it('throws Unknown tool when execute is called with an unregistered name', async () => {
    const registry = new ToolRegistry();

    const message = await registry
      .execute('missing_tool', {})
      .then(() => 'resolved')
      .catch((error: Error) => error.message);

    expect(message).toBe('Unknown tool: missing_tool');
  });

  it('compiles a static schema once at register time across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const definition: ToolDefinition = {
      name: 'static_weather',
      description: 'Reads inputSchema through a getter to count accesses',
      get inputSchema(): Record<string, unknown> {
        schemaReads += 1;
        return {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        };
      },
    };
    registry.register(definition, async input => String(input.location));

    const results: string[] = [];
    for (let index = 0; index < 10; index += 1) {
      const response = await registry.execute('static_weather', {location: 'Berlin'});
      results.push(response.result);
    }

    expect({schemaReads, callCount: results.length}).toEqual({
      schemaReads: 1,
      callCount: 10,
    });
  });

  it('validates a function-valued tool against its current schema on each execute call', async () => {
    const registry = new ToolRegistry();
    const citySchema: Record<string, unknown> = {
      type: 'object',
      properties: {city: {type: 'string'}},
      required: ['city'],
    };
    const countrySchema: Record<string, unknown> = {
      type: 'object',
      properties: {country: {type: 'string'}},
      required: ['country'],
    };
    let activeSchema = citySchema;
    registry.register(
      () => ({
        name: 'dynamic_lookup',
        description: 'Switches schemas between calls',
        inputSchema: activeSchema,
      }),
      async () => 'ok'
    );

    const firstValid = await registry.execute('dynamic_lookup', {city: 'Paris'});
    const cachedValid = await registry.execute('dynamic_lookup', {city: 'Lyon'});
    activeSchema = countrySchema;
    const rejectedAfterSwitch = await registry.execute('dynamic_lookup', {city: 'Paris'});
    const acceptedAfterSwitch = await registry.execute('dynamic_lookup', {country: 'FR'});

    expect({
      firstResult: firstValid.result,
      cachedResult: cachedValid.result,
      rejectedMentionsCountry: rejectedAfterSwitch.result.includes('country'),
      acceptedResult: acceptedAfterSwitch.result,
    }).toEqual({
      firstResult: 'ok',
      cachedResult: 'ok',
      rejectedMentionsCountry: true,
      acceptedResult: 'ok',
    });
  });
});

function weatherDefinition(): ToolDefinition {
  return {
    name: 'get_weather',
    description: 'Weather lookup tool',
    inputSchema: {
      type: 'object',
      properties: {
        location: {type: 'string'},
        units: {type: 'string', enum: ['celsius', 'fahrenheit'], default: 'celsius'},
      },
      required: ['location'],
    },
  };
}

